import os, glob, re, json

def load():
    d = os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t = open(d + '/../../sessions/' + os.path.basename(d) + '.jsonl').read().replace('\\n', '\n')
    G = {}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', t):
        k, h, w = m[1], int(m[2]), int(m[3])
        # More careful parsing - get exact height from after the match end
        content = t[m.end():]
        lines = []
        for line in content.split('\n'):
            stripped = line.strip()
            if stripped:
                parts = stripped.split()
                if len(parts) >= w:
                    rows = [parts[j] for j in range(w)]
                    lines.append([int(x) for x in rows])
                elif len(parts) < w:
                    break
        G[k] = lines
    return G

G = load()
print("All keys:", list(G.keys()))

for k in sorted(G.keys()):
    print(f"\n{'='*40}")
    print(f"{k}: {len(G[k])}x{len(G[k][0]) if G[k] else 'empty'}")
    for i, row in enumerate(G[k]):
        print(f"  Row {i}: {row}")
